```tsx
import type { ReactElement } from "react";
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;

  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;

  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;

  /** Accessible name for the group of actions. */
  groupLabel?: string;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
  groupLabel = "Actions",
}: ButtonRowProps): ReactElement {
  return (
    <div className="button-row" role="group" aria-label={groupLabel}>
      <button
        type="button"
        className="button-row__btn button-row__btn--primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>

      <button
        type="button"
        className="button-row__btn button-row__btn--secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>

      <button
        type="button"
        className="button-row__btn button-row__btn--quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1.2vw, 0.875rem);
}

.button-row__btn {
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1rem);
  font-weight: 600;
  line-height: 1;
  min-height: 2.5rem;
  padding: 0.6rem 1.25rem;
  border-radius: 999px;
  border: 1px solid transparent;
  background-color: transparent;
  color: var(--ink);
  cursor: pointer;
  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    text-decoration-color 150ms ease;
}

/* Primary: the main action. Text on a solid --myelin fill uses --slide. */
.button-row__btn--primary {
  background-color: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.button-row__btn--primary:hover:not(:disabled) {
  border-color: var(--ink);
}

/* Secondary: outlined, ink border as in the default button. */
.button-row__btn--secondary {
  border-color: var(--ink);
  color: var(--ink);
}

.button-row__btn--secondary:hover:not(:disabled) {
  background-color: var(--myelin-wash);
  border-color: var(--myelin);
  color: var(--myelin);
}

/* Quiet: text only, no fill and no border. */
.button-row__btn--quiet {
  padding-inline: 0.5rem;
  color: var(--muted);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 0.25em;
}

.button-row__btn--quiet:hover:not(:disabled) {
  color: var(--ink);
  text-decoration-color: currentColor;
}

/* Disabled: no opacity, which would lower text contrast. Use tokens instead. */
.button-row__btn:disabled {
  cursor: not-allowed;
}

.button-row__btn--primary:disabled {
  background-color: transparent;
  border-color: var(--hair);
  color: var(--muted);
}

.button-row__btn--secondary:disabled {
  border-color: var(--hair);
  color: var(--muted);
}

.button-row__btn--quiet:disabled {
  color: var(--muted);
  text-decoration-color: transparent;
}

:root[data-motion="reduce"] .button-row__btn {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__btn {
    transition: none;
  }
}
